parameters.jsCode:
const item = $input.first().json;

function cleanBody(text) {
  if (!text) return "";
  let cleaned = text.split(/\nOn .* wrote:\n/)[0];
  cleaned = cleaned.split(/\n>+/)[0];
  return cleaned.trim();
}

function escapeForJson(str) {
  return JSON.stringify(str).slice(1, -1);
}

const cleanedBody = cleanBody(item.text || item.textAsHtml || "");

return {
  json: {
    gmail_id: item.id,                          // NEW: internal Gmail ID for API actions
    message_id: item.messageId || item.id,       // RFC Message-ID, for logging/threading reference
    thread_id: item.threadId,
    sender_name: item.from?.value?.[0]?.name || "",
    sender_email: item.from?.value?.[0]?.address || "",
    subject: item.subject || "",
    body: cleanedBody,
    subject_escaped: escapeForJson(item.subject || ""),
    sender_email_escaped: escapeForJson(item.from?.value?.[0]?.address || ""),
    body_escaped: escapeForJson(cleanedBody),
    timestamp: item.date,
    has_attachments: !!(item.attachments && item.attachments.length > 0),
    attachments: item.attachments || []
  }
};

parameters.jsonBody:
={
  "model": "openai/gpt-oss-20b",
  "messages": [
    {
      "role": "system",
      "content": "You are an email classification engine for a real estate company inbox. Classify the email into exactly one category, assign a priority, and decide if human review is required. Important edge cases: (1) Legitimate transactional notifications from banks, payment processors, or service providers (e.g. UBL, HBL, PayPal, Stripe transaction alerts, OTPs, bill reminders) are NOT spam or promotional, even if they contain standard fraud-warning boilerplate text — classify these as 'other' with low priority and requires_human=false. (2) Only classify as 'spam' if the email is unsolicited bulk mail, phishing with suspicious links/sender mismatch, or clearly irrelevant mass marketing (e.g. LinkedIn network suggestions, newsletters you didn't request). (3) Classify as 'promotional' only for legitimate marketing/sales emails from known senders, not phishing. When in doubt between spam and other, prefer 'other' with lower confidence rather than aggressively marking as spam — the system must never delete a legitimate business email. Respond with ONLY valid JSON, no markdown, no explanation. Schema: {\"category\": one of [general_query, sales_inquiry, job_application, project_related, internal_communication, meeting_request, urgent_request, complaint, promotional, spam, other], \"priority\": one of [low, medium, high, critical], \"requires_human\": true or false, \"confidence\": number between 0 and 1, \"reasoning\": short string}"
    },
    {
      "role": "user",
      "content": "Subject: {{ $('Code in JavaScript').item.json.subject_escaped }}\n\nFrom: {{ $('Code in JavaScript').item.json.sender_email_escaped }}\n\nBody:\n{{ $('Code in JavaScript').item.json.body_escaped }}"
    }
  ],
  "temperature": 0.2,
  "response_format": { "type": "json_object" }
}

parameters.jsCode:
const response = $input.first().json;
const raw = response.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    category: "other",
    priority: "medium",
    requires_human: true,
    confidence: 0,
    reasoning: "Failed to parse LLM output: " + raw
  };
}

// Merge classification with the original email data
const emailData = $('Code in JavaScript').item.json;

return {
  json: {
    ...emailData,
    category: parsed.category,
    priority: parsed.priority,
    requires_human: parsed.requires_human,
    confidence: parsed.confidence,
    reasoning: parsed.reasoning
  }
};

